module mod_mult #(
    parameter n = 5,
    parameter delta = -13,
    parameter modulus = 19
)(
    input [n-1:0] a,
    input [n-1:0] b,
    input delta_a,
    input delta_b,
    output reg [n-1:0] p,
    output reg delta_p
);

    wire [2:0] AH = a[n-1:2];
    wire [1:0] AL = a[1:0];
    wire [2:0] BH = b[n-1:2];
    wire [1:0] BL = b[1:0];

    wire [n-1:0] pp_ll;
    wire [n-1:0] pp_lh;
    wire [n-1:0] pp_hl;
    wire [n-1:0] pp_hh;

