        .address({AL, delta_a, BL, delta_b}),
        .data(pp_ll)
    );

    logic_mod19_minus_LH logic_lh (
        .address({AL, delta_a, BH}),
        .data(pp_lh)
    );

    logic_mod19_minus_HL logic_hl (
        .address({AH, BL, delta_b}),
        .data(pp_hl)
    );

    logic_mod19_minus_HH logic_hh (
        .address({AH, BH}),
        .data(pp_hh)
    );

    wire [n:0] sum1;
    wire [n:1] carry1;
    wire [n-1:0] cout_vec;

    compressor4_2 comp0 (
        .x1(pp_ll[0]),
        .x2(pp_hl[0]),
        .x3(pp_lh[0]),
        .x4(pp_hh[0]),
        .cin(1'b0),
        .sum(sum1[0]),
        .carry(carry1[1]),
        .cout(cout_vec[0])
    );

    genvar i;
    generate
        for (i = 1; i < 5; i = i + 1) begin : compressor_stage1
            compressor4_2 comp1 (
                .x1(pp_ll[i]),
                .x2(pp_hl[i]),
                .x3(pp_lh[i]),
                .x4(pp_hh[i]),
                .cin(cout_vec[i-1]),
                .sum(sum1[i]),
                .carry(carry1[i+1]),
                .cout(cout_vec[i])
            );
        end
    endgenerate

    assign sum1[n] = cout_vec[n-1];

    wire [n:0] logic_data;

    logic_rom_mult_minus_19 logic_rom_0 (
        .address({sum1[n], carry1[n], sum1[n-1], carry1[n-1]}),
        .data(logic_data)
    );

    wire [n-2:0] csa_sum;
    wire [n-1:1] csa_carry;

    csa #(
        .n(n)
    ) csa_0 (
        .a(logic_data[n-2:0]),
        .b(sum1[n-2:0]),
        .c({carry1[n-2:1], 1'b0}),
        .sum_out(csa_sum),
        .carry_out(csa_carry)
    );

    wire [n:0] y;
    wire delta_aux;
    assign y = {logic_data[n-1], csa_sum} + {csa_carry, 1'b0};

    assign delta_aux = logic_data[n] ^ y[n];

    always @(*) begin
        p = y[n-1:0];
        delta_p = delta_aux;
    end
endmodule
